getVisibleColumnFromPosition(rawPosition) {
        if (!this.tb) {
            return rawPosition.column;
        }
        const position = this.tb.model.validatePosition(rawPosition);
        const tabSize = this.tb.model.getOptions().tabSize;
        return $lF.visibleColumnFromColumn(this.tb.model.getLineContent(position.lineNumber), position.column, tabSize) + 1;
    }
